-- 只调整项目预置数据中确切匹配的展示文字，不覆盖用户填写的报告内容。
START TRANSACTION;
UPDATE users SET realName=CASE userId WHEN '19900000001' THEN '林晨' WHEN '19900000002' THEN '苏雅' WHEN '19900000003' THEN '陆航' WHEN '19900000004' THEN '许宁' WHEN '19900000005' THEN '周安' END
 WHERE (userId='19900000001' AND realName='演示患者甲') OR (userId='19900000002' AND realName='演示患者乙') OR (userId='19900000003' AND realName='演示患者丙') OR (userId='19900000004' AND realName='演示患者丁') OR (userId='19900000005' AND realName='演示患者戊');
UPDATE orders SET patientName=CASE patientName WHEN '演示患者甲' THEN '林晨' WHEN '演示患者乙' THEN '苏雅' WHEN '演示患者丙' THEN '陆航' WHEN '演示患者丁' THEN '许宁' WHEN '演示患者戊' THEN '周安' WHEN '演示家属丙' THEN '陆岚' END
 WHERE (userId='19900000001' AND patientName='演示患者甲') OR (userId='19900000002' AND patientName='演示患者乙') OR (userId='19900000003' AND patientName IN ('演示患者丙','演示家属丙')) OR (userId='19900000004' AND patientName='演示患者丁') OR (userId='19900000005' AND patientName='演示患者戊');
UPDATE doctor SET realName=CASE docCode WHEN 'doctor01' THEN '刘明' WHEN 'doctor02' THEN '陈宁' WHEN 'doctor03' THEN '林悦' END WHERE (docCode='doctor01' AND realName='示例医生') OR (docCode='doctor02' AND realName='演示医生乙') OR (docCode='doctor03' AND realName='演示医生丙');
UPDATE hospital SET name='东软健康体检中心',address=CASE WHEN address='示例市健康路1号' THEN '健康路 1 号' ELSE address END WHERE hpId=1 AND name='示例体检中心';
UPDATE hospital SET name=CASE name WHEN '演示体检中心·和平院区' THEN '东软体检中心·和平院区' WHEN '演示体检中心·浑南院区' THEN '东软体检中心·浑南院区' END,address=CASE address WHEN '示例市和平路 1 号' THEN '和平路 1 号' WHEN '示例市健康路 2 号' THEN '健康路 2 号' ELSE address END,`rule`=CASE WHEN `rule`='仅供演示，请提前预约' THEN '请提前预约' ELSE `rule` END WHERE name IN ('演示体检中心·和平院区','演示体检中心·浑南院区');
UPDATE setmeal SET name=CASE name WHEN '演示·男士基础体检' THEN '男士健康体检套餐' WHEN '演示·女士基础体检' THEN '女士健康体检套餐' WHEN '演示·男士肝功能体检' THEN '男士肝功能体检套餐' WHEN '演示·女士肾功能体检' THEN '女士肾功能体检套餐' END WHERE name IN ('演示·男士基础体检','演示·女士基础体检','演示·男士肝功能体检','演示·女士肾功能体检');
UPDATE checkitemdetailed d JOIN checkitem c ON c.ciId=d.ciId SET d.name=CASE d.name WHEN '演示身高' THEN '身高' WHEN '演示体重' THEN '体重' WHEN '演示白细胞' THEN '白细胞计数' WHEN '演示血小板' THEN '血小板计数' WHEN '演示肝功能指标' THEN '肝功能指标' WHEN '演示肾功能指标' THEN '肾功能指标' ELSE d.name END,d.normalValueString=CASE WHEN d.normalValueString='仅供演示' THEN NULL ELSE d.normalValueString END WHERE c.ciName IN ('演示·一般检查','演示·血常规','演示·肝功能','演示·肾功能') AND d.remarks='非临床数据';
UPDATE checkitem SET ciContent=CASE ciContent WHEN '身高与体重示例' THEN '身高与体重检查' WHEN '血常规示例项目' THEN '血液常规项目检查' WHEN '肝功能示例项目' THEN '肝功能项目检查' WHEN '肾功能示例项目' THEN '肾功能项目检查' ELSE ciContent END,meaning=CASE meaning WHEN '用于展示一般检查项目' THEN '了解基础身体状况' WHEN '用于展示检查结果' THEN '了解血液指标' WHEN '用于展示套餐项目' THEN '了解相关检查项目' ELSE meaning END,ciName=CASE ciName WHEN '演示·一般检查' THEN '基础体格检查' WHEN '演示·血常规' THEN '血液常规检查' WHEN '演示·肝功能' THEN '肝功能检查' WHEN '演示·肾功能' THEN '肾功能检查' END WHERE ciName IN ('演示·一般检查','演示·血常规','演示·肝功能','演示·肾功能') AND remarks='虚构数据，仅供演示';
UPDATE cireport r JOIN orders o ON o.orderId=r.orderId SET r.ciName=CASE r.ciName WHEN '演示·一般检查' THEN '基础体格检查' WHEN '演示·血常规' THEN '血液常规检查' WHEN '演示·肝功能' THEN '肝功能检查' WHEN '演示·肾功能' THEN '肾功能检查' END WHERE o.userId IN ('19900000001','19900000005') AND r.ciName IN ('演示·一般检查','演示·血常规','演示·肝功能','演示·肾功能');
UPDATE cidetailedreport d JOIN orders o ON o.orderId=d.orderId SET d.name=CASE d.name WHEN '演示身高' THEN '身高' WHEN '演示体重' THEN '体重' WHEN '演示白细胞' THEN '白细胞计数' WHEN '演示血小板' THEN '血小板计数' WHEN '演示肝功能指标' THEN '肝功能指标' WHEN '演示肾功能指标' THEN '肾功能指标' END,d.value=CASE d.value WHEN '示例异常' THEN '偏高' WHEN '示例正常' THEN '正常' ELSE d.value END,d.normalValueString=CASE WHEN d.normalValueString='仅供演示' THEN NULL ELSE d.normalValueString END WHERE o.userId IN ('19900000001','19900000005') AND d.name IN ('演示身高','演示体重','演示白细胞','演示血小板','演示肝功能指标','演示肾功能指标');
UPDATE overallresult r JOIN orders o ON o.orderId=r.orderId SET r.title='总检结论',r.content='体检报告已完成，请查看各项检查结果。' WHERE o.userId IN ('19900000001','19900000005') AND r.title='演示总检结论' AND r.content='虚构体检数据，仅用于页面和流程演示，不作为诊疗依据。';
COMMIT;
